"""Canonical layer-zero declaration builder (lock generated by tasks_v2.decl)."""

from opulse.atoms import nodes as n

from .world import bind_body

HOST = "opulse.worlds_v2.hidden.hosts:"
ZERO = "0" * 64


def operation(name, inputs, output, rule, *, role="transform", errors=()):
    return {"kind": "operation", "name": name, "symbol": name, "role": role,
            "inputs": [{"name": f"arg{index}", "sort": sort, "enter": "bottom"}
                       for index, sort in enumerate(inputs)],
            "output": {"sort": output, "enter": "bottom"}, "rule": rule,
            "errors": list(errors), "cost": 1, "strict": True, "reads_params": [],
            "impl": {"host": HOST + name, "digest": ZERO}}


def obj(name, form="given", **extras):
    return {"kind": "object", "name": name, "form": form, "base": None, "tags": None,
            "group": [], "valid": None, "canon": None, "sealed": False,
            "interface": [], "params": [], "equality": "canonical", "canon_cost": "counted",
            "body": None, "host": None, "doc": ("Sealed card and full state; never passed to the receiver."
                                                  if name == "Truth" else f"Finite public {name} values."), **extras}


def build():
    specifications = (
        ("channel", ("Mode", "str"), "DistLamp", "Public conditional lamp distribution."),
        ("signal", ("Truth", "Mode"), "DistTruth", "Trusted sealed conditional transition."),
        ("guess", ("ReceiverView", "str"), "ReceiverView", "Append a receiver guess."),
        ("eq", ("any", "any"), "bool", "Exact finite equality."),
        ("lt", ("Rational", "Rational"), "bool", "Strict rational comparison."),
        ("le", ("Rational", "Rational"), "bool", "Weak rational comparison."),
        ("add", ("Rational", "Rational"), "Rational", "Exact rational addition."),
        ("mul", ("Rational", "Rational"), "Rational", "Exact rational product."),
        ("div", ("Rational", "Rational"), "Rational", "Exact nonzero rational quotient."),
        ("sub", ("Rational", "Rational"), "Rational", "Exact rational difference."),
        ("ratio", ("int", "int"), "Rational", "Canonical rational constructor."),
        ("weight", ("DistLamp", "Lamp"), "Rational", "Project a public lamp likelihood."),
        ("mode_cost", ("Mode",), "int", "Read public A=3 or B=1 cost."),
        ("history", ("ReceiverView",), "History", "Read the receiver's public history."),
        ("step_lamp", ("Step",), "Lamp", "Project the public lamp of a step."),
        ("empty", ("any",), "bool", "Test an arbitrary finite list."),
        ("head", ("any",), "any", "Project its first list item."),
        ("tail", ("any",), "any", "Drop its first list item."),
        ("prepend", ("any", "any"), "any", "Prepend a finite-list item."),
        ("reverse", ("any",), "any", "Reverse a finite list."),
        ("size", ("any",), "int", "Count finite-list items."),
        ("less_int", ("int", "int"), "bool", "Compare public integer budgets."),
        ("decrease", ("int", "int"), "int", "Subtract a public mode cost."),
        ("fail", ("str",), "any", "Produce a declared domain failure."),
        ("node_leaf", ("str",), "PolicyNode", "Construct a guess leaf."),
        ("node_ask", ("Mode", "PolicyNode", "PolicyNode"), "PolicyNode", "Construct a red-blue decision node."),
        ("node_is_ask", ("PolicyNode",), "bool", "Distinguish branches from leaves."),
        ("node_valid", ("PolicyNode",), "bool", "Check a finite well-formed policy tree."),
        ("node_choice", ("PolicyNode",), "str", "Read the choice in a leaf."),
        ("node_mode", ("PolicyNode",), "Mode", "Read the mode at a branch."),
        ("node_red", ("PolicyNode",), "PolicyNode", "Read its red child."),
        ("node_blue", ("PolicyNode",), "PolicyNode", "Read its blue child."),
        ("dist_items", ("DistTruth",), "Branches", "Read finite distribution entries."),
        ("dist_make", ("Branches",), "DistTruth", "Construct a finite distribution from entries."),
        ("branch", ("any", "Rational"), "Branch", "Construct a weighted value."),
        ("branch_value", ("Branch",), "any", "Read a weighted value."),
        ("branch_weight", ("Branch",), "Rational", "Read a branch's exact weight."),
        ("singleton", ("any",), "DistTruth", "Construct a unit-mass distribution."),
        ("duplicate", ("any",), "DistTruth", "Construct two equal half-mass branches."),
    )
    operations = [operation(*item) for item in specifications]
    for item in operations:
        if item["name"] == "signal":
            item["role"] = "act"
        if item["name"] in ("lt", "le", "eq", "less_int"):
            item["role"] = "relate"
        if item["name"] in ("div",):
            item["errors"] = ["impossible"]
        if item["name"] in ("decrease",):
            item["errors"] = ["budget"]
        if item["name"] == "fail":
            item["errors"] = ["unpaired", "budget", "invalid"]
        if item["name"] in ("head", "tail"):
            item["errors"] = ["empty"]
    return {"schema": "opulse.world/2", "world": "hidden", "version": 1, "dialect": "atoms-v2",
            "title": "Sealed Cards and Budgeted Channels", "source": {"title_zh": "暗牌信道与有限预算决策"},
            "params": {"cards": 2, "lamps": 2, "modes": 2, "max_budget": 12},
            "constants": {"prior": [1, 2], "cost": {"A": 3, "B": 1}},
            "objects": [obj(name, sealed=name == "Truth", interface=["signal"] if name == "Truth" else []) for name in
                        ("Truth", "ReceiverView", "Mode", "Lamp", "Modes", "Lamps",
                         "History", "Step", "PolicyNode", "Rational", "DistLamp", "DistTruth", "BeliefPair",
                         "int", "str", "bool", "any", "Branches", "Branch")],
            "operations": operations + [
                {**operation(name, signature, output, rule),
                 "impl": {"host": HOST + function, "digest": ZERO}}
                for name, function, signature, output, rule in (
                    ("BeliefPair.pair", "pair", ("Rational", "Rational"), "BeliefPair", "Construct a public rational pair."),
                    ("BeliefPair.r", "pair_r", ("BeliefPair",), "Rational", "Read its first component."),
                    ("BeliefPair.b", "pair_b", ("BeliefPair",), "Rational", "Read its second component."))],
            "combinators": {"nodes": ["Var", "Lit", "Call", "Let", "Case", "Rec"],
                            "library": [{"name": "bind", "params": ["f", "distribution"],
                                         "op_params": ["f"], "unfold_rule": "substitute",
                                         "rule": "Bind finite distributions and combine equal weighted results.",
                                         "body": n.to_json(bind_body())}], "recursion": "fuel"},
            "observation": {"truth": "Truth", "probes": [
                {"name": name, "sort": sort, "reads": "Truth", "reveals": reveals,
                 "impl": {"host": HOST + name, "digest": ZERO}}
                for name, sort, reveals in (("receiver", "ReceiverView", ["history", "actions"]),
                                            ("judge", "bool", ["correct"]))],
                "capabilities": {"receiver": {"probes": ["receiver"]},
                                 "judge": {"probes": ["judge"]}},
                "show": {"receiver": ["history", "actions"],
                         "judge": ["card", "history", "actions"]}, "judge_view": "full_state"},
            "codec": {}, "lock": {}}
